-- (KItemList::ExecuteScript only calls main; this script never removes the item). Generated by
-- scratchpad\lbdaosi\gen.py - edit the generator, not this file. Doc: docs\features\lenh-bai-dao-si-phong-than-20261004.md
-- Right click (Dao Si only): skill set of the client auto fight (PhongThanAutoFight.inl, Alt+A/S/D) by element:
-- Tho + Hoa + Bang (default), Hoa + Bang + Loi, all, one element, or skill by skill per element (also the 3 buffs);
-- r2: rows Bat dau / Dung tu dong danh, and choosing a set starts the auto fight (task 2617 command, option 2618),
-- by the auto). Stored in task 2613 (0 = skills on the keys; else 2^30 + sum 2^(id - 3)), sent to the client with
-- SyncTaskValue (VNG s2c_synctaskvalue). Menus <= 7 rows; only learnt skills are listed.
-- Lua 4 / engine: no top-level dofile, one small statement per record (stack 120 slots).

PTLB_T_DS = 2613      -- Dao Si set: 0 = keys, else 2^30 + sum 2^(id - 3), ids 3..26
PTLB_T_DN = 2614      -- Di Nhan set: 0 = off, else 2^30 + sum 2^(id - 43), ids 43..51
PTLB_T_GDS = 2615     -- 1 = Lenh Bai Dao Si given (auto gift)
PTLB_T_GDN = 2616     -- 1 = Lenh Bai Di Nhan given (auto gift)
PTLB_ITEM_DS = 61480
PTLB_ITEM_DN = 61481
PTLB_T_GS = 2619      -- Giap Si set: 0 = keys, else 2^30 + sum 2^(id - 27), ids 27..42
PTLB_T_GGS = 2620     -- 1 = Lenh Bai Giap Si given (auto gift)
PTLB_ITEM_GS = 61482
PTLB_FLAG = 1073741824
PTLB_T_CMD = 2617     -- start / stop request for the client auto fight: sequence x 4 + 1 (start) / 2 (stop)
PTLB_T_PREF = 2618    -- 0 = start the auto fight when a set is chosen (default), 1 = do not

function PTLB_No()
end

function PTLB_Say(title, o)
	local n = getn(o)
	local t = { title, n }
	local k = 1
	while k <= n do t[k + 2] = o[k] k = k + 1 end
	call(Say, t)
end

function PTLB_Pow(k)
	local v = 1
	local i = 0
	while i < k do v = v * 2 i = i + 1 end
	return v
end

-- 1 when bit k of v is set (Lua 4: no bit operators)
function PTLB_Bit(v, k)
	local q = floor(v / PTLB_Pow(k))
	if q - floor(q / 2) * 2 == 1 then return 1 end
	return nil
end

function PTLB_Learnt(id)
	local l = HaveMagic(id)
	if l and l > 0 then return 1 end
	return nil
end

function PTLB_AddSk(t, id, el, kind, nm, grp)
	local s = {}
	s.grp = grp
	s.id = id
	s.el = el
	s.kind = kind
	s.nm = nm
	t.n = t.n + 1
	t[t.n] = s
end

function PTLB_AddPS(prof, id, mx, tier, nm)
	local s = {}
	s.id = id
	s.mx = mx
	s.tier = tier
	s.nm = nm
	tinsert(PTLB_PS[prof], s)
end

-- skills of the profession the character may raise now (rebirth skills once their level is reached)
function PTLB_ProfList(prof)
	PTLB_Load()
	local r = {}
	local t = PTLB_PS[prof]
	if not t then return r end
	local lv = GetLevel()
	local i = 1
	while t[i] do
		if t[i].tier <= lv then tinsert(r, t[i]) end
		i = i + 1
	end
	return r
end

function PTLB_FindPS(prof, id)
	local l = PTLB_ProfList(prof)
	local i = 1
	while l[i] do
		if l[i].id == id then return l[i], i end
		i = i + 1
	end
	return nil, 0
end

function PTLB_Lv(id)
	local l = HaveMagic(id)
	if l and l > 0 then return l end
	return 0
end

-- learn (if needed) and set skill s to its max level, as the web admin does (SetSkillLevel + AddMagic, which
-- syncs the client skill bar). Skill points are neither spent nor refunded. 1 when the level is reached.
function PTLB_MaxOne(s)
	if PTLB_Lv(s.id) >= s.mx then return 1 end
	SetSkillLevel(s.id, s.mx)
	AddMagic(s.id, s.mx)
	if PTLB_Lv(s.id) >= s.mx then return 1 end
	return 0
end

function PTLB_MaxAll(prof)
	local l = PTLB_ProfList(prof)
	local ok = 0
	local i = 1
	while l[i] do
		ok = ok + PTLB_MaxOne(l[i])
		i = i + 1
	end
	return ok, getn(l)
end

