	return "<color=yellow>L\214nh B\181i \167\185o S\220<color>: b\233 chi\170u t\249 \174\184nh lu\169n phi\170n. Hi\214n t\185i: <color=green>" .. PTLB_DescDS(GetTask(PTLB_T_DS)) .. "<color>. Ch\228n b\233 l\181 t\249 b\203t t\249 \174\184nh; Alt+A c\242ng b\203t ho\198c t\190t."
end

-- attack skills of the given elements replace the attack part; the chosen buffs stay
function PTLBDS_SetEls(e1, e2, e3, e4)
	PTLB_Load()
	local v = GetTask(PTLB_T_DS)
	local i = 1
	while i <= PTLB_DS.n do
		local s = PTLB_DS[i]
		if s.kind == 1 then
			if s.el == e1 or s.el == e2 or s.el == e3 or s.el == e4 then v = PTLB_With(PTLB_DS, v, s.id) else v = PTLB_Without(PTLB_DS, v, s.id) end
		end
		i = i + 1
	end
	PTLB_Apply(PTLB_T_DS, v)
	local n, a = PTLB_Count(PTLB_DS, v)
	Msg2Player("L\214nh B\181i \167\185o S\220: b\233 chi\170u " .. PTLB_DescDS(v) .. " - t\249 \174\184nh lu\169n phi\170n " .. a .. " chi\170u \174\184nh \174\183 h\228c.")
	if a == 0 then Msg2Player("B\185n ch\173a h\228c chi\170u \174\184nh n\181o c\241a h\214 \174\183 ch\228n: t\249 \174\184nh t\185m d\239ng chi\170u \174ang g\184n \235 ph\221m.") end
	PTLBDS_After()
end

