	o[2] = "H\214 H\225a" .. " (" .. PTLB_GroupCount(PTLB_DS, v, 2) .. " \174ang b\203t)" .. "/PTLBDS_G2"
	o[3] = "H\214 B\168ng" .. " (" .. PTLB_GroupCount(PTLB_DS, v, 3) .. " \174ang b\203t)" .. "/PTLBDS_G3"
	o[4] = "H\214 L\171i" .. " (" .. PTLB_GroupCount(PTLB_DS, v, 4) .. " \174ang b\203t)" .. "/PTLBDS_G4"
	o[5] = "Buff h\214" .. " (" .. PTLB_GroupCount(PTLB_DS, v, 5) .. " \174ang b\203t)" .. "/PTLBDS_G5"
	o[6] = "Quay l\185i/PTLBDS_Main"
	o[7] = "\167\227ng/PTLB_No"
	PTLB_Say("<color=yellow>L\214nh B\181i \167\185o S\220<color>: ch\228n nh\227m chi\170u, r\229i b\202m t\245ng chi\170u \174\211 b\203t ho\198c t\190t. [B\203T] = t\249 \174\184nh d\239ng chi\170u \174\227. Ch\216 hi\214n chi\170u \174\183 h\228c.", o)
end

function PTLBDS_Group(g)
	PTLB_Load()
	local l = PTLB_GroupList(PTLB_DS, g)
	local v = GetTask(PTLB_T_DS)
	local names = { "H\214 Th\230", "H\214 H\225a", "H\214 B\168ng", "H\214 L\171i", "Buff h\214" }
	if getn(l) == 0 then
		Say("<color=yellow>L\214nh B\181i \167\185o S\220<color>: b\185n ch\173a h\228c chi\170u n\181o c\241a nh\227m " .. names[g] .. ".", 2, "Quay l\185i/PTLBDS_Groups", "\167\227ng/PTLB_No")
		return
	end
	local o = {}
	local n = 0
	local i = 1
	while l[i] do
		local s = PTLB_DS[l[i]]
		local m = "[t\190t] "
		if PTLB_Has(PTLB_DS, v, s.id) then m = "[B\203T] " end
		n = n + 1
		o[n] = m .. s.nm .. "/PTLBDS_T" .. l[i]
		i = i + 1
	end
	if n <= 5 then n = n + 1 o[n] = "Xong, b\190t \174\199u t\249 \174\233ng \174\184nh/PTLBDS_Start" end
	n = n + 1 o[n] = "Quay l\185i/PTLBDS_Groups"
	if n < 7 then n = n + 1 o[n] = "\167\227ng/PTLB_No" end
	PTLB_Say("<color=yellow>L\214nh B\181i \167\185o S\220<color>: nh\227m " .. names[g] .. " - b\202m m\233t chi\170u \174\211 b\203t ho\198c t\190t (\174ang b\203t " .. PTLB_GroupCount(PTLB_DS, v, g) .. ").", o)
end

