function PTLBDS_UpPage(pg)
	local l = PTLB_ProfList(1)
	local last = floor((getn(l) + 4) / 5)
	if last < 1 then last = 1 end
	if pg > last then pg = last end
	local o = {}
	local n = 0
	local i = (pg - 1) * 5 + 1
	while i <= pg * 5 and l[i] do
		local s = l[i]
		local lv = PTLB_Lv(s.id)
		local d = " (c\202p " .. lv .. " trong " .. s.mx .. ")"
		if lv <= 0 then d = " (ch\173a h\228c, t\232i \174a " .. s.mx .. ")" end
		if lv >= s.mx then d = " (\174\183 t\232i \174a " .. s.mx .. ")" end
		n = n + 1
		o[n] = s.nm .. d .. "/PTLBDS_U" .. s.id
		i = i + 1
	end
	if pg < last then n = n + 1 o[n] = "Trang sau " .. (pg + 1) .. "/PTLBDS_UP" .. (pg + 1) end
	n = n + 1 o[n] = "Quay l\185i/PTLBDS_Up"
	if n < 7 then n = n + 1 o[n] = "\167\227ng/PTLB_No" end
	PTLB_Say("<color=yellow>L\214nh B\181i \167\185o S\220<color>: ch\228n k\252 n\168ng \174\211 n\169ng l\170n c\202p t\232i \174a (trang " .. pg .. " " .. "trong " .. last .. ").", o)
end

