function PTLBDS_UpOne(id)
	local s = PTLB_FindPS(1, id)
	if not s then return end
	if PTLB_Lv(id) >= s.mx then
		Msg2Player("L\214nh B\181i \167\185o S\220: " .. s.nm .. " \174\183 \235 c\202p t\232i \174a " .. s.mx .. ".")
		PTLBDS_UpShow(id)
		return
	end
	Say("<color=yellow>L\214nh B\181i \167\185o S\220<color>: n\169ng " .. s.nm .. " l\170n c\202p t\232i \174a " .. s.mx .. "?", 2, "\167\229ng \253/PTLBDS_Y" .. id, "Kh\171ng/PTLBDS_Up")
end

function PTLBDS_UpOk(id)
	local s = PTLB_FindPS(1, id)
	if not s then return end
	if PTLB_MaxOne(s) > 0 then
		Msg2Player("L\214nh B\181i \167\185o S\220: \174\183 n\169ng " .. s.nm .. " l\170n c\202p " .. s.mx .. ".")
	else
		Msg2Player("L\214nh B\181i \167\185o S\220: kh\171ng n\169ng \174\173\238c " .. s.nm .. ".")
	end
	PTLBDS_UpShow(id)
end

-- show the upgrade page holding skill id
function PTLBDS_UpShow(id)
	local s, pos = PTLB_FindPS(1, id)
	if pos < 1 then pos = 1 end
	PTLBDS_UpPage(floor((pos - 1) / 5) + 1)
end

